#include <cstdint>
#include <iostream>

void dive(int depth, std::uintptr_t previous)
{
    int marker{depth};
    std::cout << depth << ' ' << static_cast<const void*>(&marker) << '\n';
    if (depth < 10) dive(depth + 1, reinterpret_cast<std::uintptr_t>(&marker));
}

int main()
{
    dive(0, 0);
}
